"""Landauer kT ln 2 bound for one-bit erasure under the Jarzynski equality."""
from __future__ import annotations
import math
from typing import Sequence

K_B: float = 1.380649e-23

def expect(p: Sequence[float], f: Sequence[float]) -> float:
    return sum(pi * fi for pi, fi in zip(p, f))

def jarzynski_lhs(p: Sequence[float], w: Sequence[float], alpha: float) -> float:
    return expect(p, [math.exp(-alpha * wi) for wi in w])

def landauer_demo() -> None:
    k, T = K_B, 300.0
    alpha = 1.0 / (k * T)
    df = k * T * math.log(2)                       # Landauer free-energy cost
    print(f"Landauer floor kT ln 2 = {df:.4e} J")
    for name, (p, w_raw) in {
        "deterministic": ([1.0, 0.0], [df, df]),
        "fluctuating":   ([0.5, 0.5], [0.1 * df, 3.0 * df]),
    }.items():
        # shift work to satisfy the Jarzynski equality for this df
        c = df + math.log(jarzynski_lhs(p, w_raw, alpha)) / alpha
        w = [wi + c for wi in w_raw]
        ew = expect(p, w)
        print(f"  {name:13s}: E[W] = {ew:.4e} J = {ew/df:.4f} * kT ln2"
              f"   (bound holds: {ew >= df - 1e-30})")

if __name__ == "__main__":
    landauer_demo()
